func TestReconcileFailedParents_ConstraintGateExhausted_NoNewCommits(t *testing.T) {
	orch, db, bareRepo := setupReconcileTest(t)

	// Create a feature worktree with a branch
	featureName := "constraint-gate-test-no-new"
	featureDir := createFeatureWorktree(t, bareRepo, featureName)

	// Get the HEAD SHA of the feature worktree
	headSHA, err := worktree.RunGit([]string{"rev-parse", "HEAD"}, featureDir)
	if err != nil {
		t.Fatalf("failed to get HEAD SHA: %v", err)
	}
	headSHA = headSHA[:7] // Short SHA for consistency

	parentID := uuid.New()
	parent := model.Task{
		ID:          parentID,
		ProjectID:   orch.projectID,
		Title:       "failed-parent-constraint-gate-no-new",
		Description: "parent failed due to constraint gate exhaustion with no new commits",
		Status:      model.StatusFailed,
		WorktreeBranch: "feature/" + featureName,
		Context: model.JSONField{
			"constraint_gate_exhausted": true,
			"constraint_gate_failed_at_commit": headSHA,
		},
	}
	db.Create(&parent)

	// Three DONE subtasks — mirrors the real bug scenario (3/3 done, parent stuck failed).
	for i := 0; i < 3; i++ {
		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Title:        "done-sub",
			Description:  "completed subtask",
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}
	if n != 0 {
		t.Errorf("expected 0 parents recovered (constraint gate exhausted with no new commits), got %d", n)
	}

	// Parent should remain FAILED.
	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status != model.StatusFailed {
		t.Errorf("expected parent status failed, got %s", updated.Status)
	}

	// Check that context is still intact
	if !updated.Context["constraint_gate_exhausted"].(bool) {
		t.Error("constraint_gate_exhausted should still be true in context")
	}

	if updated.Context["constraint_gate_failed_at_commit"].(string) != headSHA {
		t.Error("constraint_gate_failed_at_commit should still match original SHA")
	}
}

func TestReconcileFailedParents_ConstraintGateExhausted_NewCommit(t *testing.T) {
	orch, db, bareRepo := setupReconcileTest(t)

	// Create a feature worktree with a branch
	featureName := "constraint-gate-test-new-commit"
	featureDir := createFeatureWorktree(t, bareRepo, featureName)

	// Get the HEAD SHA of the feature worktree
	headSHA, err := worktree.RunGit([]string{"rev-parse", "HEAD"}, featureDir)
	if err != nil {
		t.Fatalf("failed to get HEAD SHA: %v", err)
	}
	headSHA = headSHA[:7] // Short SHA for consistency

	// Add a commit to the feature worktree to simulate new changes
	testFile := filepath.Join(featureDir, "new-file.txt")
	if err := testutil.WriteFile(testFile, "new content"); err != nil {
		t.Fatal(err)
	}
	runGitCmd(t, featureDir, "add", ".")
	runGitCmd(t, featureDir, "commit", "-m", "add new file")

	// Now get the new HEAD SHA
	newHeadSHA, err := worktree.RunGit([]string{"rev-parse", "HEAD"}, featureDir)
	if err != nil {
		t.Fatalf("failed to get new HEAD SHA: %v", err)
	}
	newHeadSHA = newHeadSHA[:7] // Short SHA for consistency

	// Ensure the SHA has changed
	if newHeadSHA == headSHA {
		t.Fatalf("Expected new commit to change HEAD SHA, but both are %s", headSHA)
	}

	parentID := uuid.New()
	parent := model.Task{
		ID:          parentID,
		ProjectID:   orch.projectID,
		Title:       "failed-parent-constraint-gate-new-commit",
		Description: "parent failed due to constraint gate exhaustion but has new commits",
		Status:      model.StatusFailed,
		WorktreeBranch: "feature/" + featureName,
		Context: model.JSONField{
			"constraint_gate_exhausted": true,
			"constraint_gate_failed_at_commit": headSHA,
		},
	}
	db.Create(&parent)

	// Three DONE subtasks — mirrors the real bug scenario (3/3 done, parent stuck failed).
	for i := 0; i < 3; i++ {
		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Title:        "done-sub",
			Description:  "completed subtask",
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}
	if n != 1 {
		t.Errorf("expected 1 parent recovered (constraint gate exhausted but new commits exist), got %d", n)
	}

	// Parent should be recovered (not FAILED anymore).
	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status == model.StatusFailed {
		t.Errorf("expected parent to be recovered from failed, still %s", updated.Status)
	}

	// Check that constraint gate context was cleared after recovery
	if updated.Context["constraint_gate_exhausted"] != nil {
		t.Error("constraint_gate_exhausted should be cleared from context after recovery")
	}

	if updated.Context["constraint_gate_failed_at_commit"] != nil {
		t.Error("constraint_gate_failed_at_commit should be cleared from context after recovery")
	}
}

func TestReconcileFailedParents_NonConstraintFailure_StillRecovers(t *testing.T) {
	orch, db, _ := setupReconcileTest(t)

	parentID := uuid.New()
	parent := model.Task{
		ID:          parentID,
		ProjectID:   orch.projectID,
		Title:       "failed-parent-non-constraint-failure",
		Description: "parent failed due to merge conflict, not constraint gate",
		Status:      model.StatusFailed,
		Context: model.JSONField{
			"failure_reason": "merge conflict",
		},
	}
	db.Create(&parent)

	// Three DONE subtasks — mirrors the real bug scenario (3/3 done, parent stuck failed).
	for i := 0; i < 3; i++ {
		sub := model.Task{
			ID:           uuid.New(),
			ProjectID:    orch.projectID,
			ParentTaskID: &parentID,
			Title:        "done-sub",
			Description:  "completed subtask",
			Status:       model.StatusDone,
		}
		db.Create(&sub)
	}

	n, err := orch.reconcileFailedParents()
	if err != nil {
		t.Fatalf("reconcileFailedParents() error: %v", err)
	}
	if n != 1 {
		t.Errorf("expected 1 parent recovered (non-constraint failure should still recover), got %d", n)
	}

	// Parent should be recovered (not FAILED anymore).
	var updated model.Task
	db.First(&updated, "id = ?", parentID)
	if updated.Status == model.StatusFailed {
		t.Errorf("expected parent to be recovered from failed, still %s", updated.Status)
	}
}"}

